// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address newDistributor) public {
        vm.assume(newDistributor != address(0));

        address oldDistributor = c.rewardDistributor();

        // The owner calls setRewardDistributor
        c.setRewardDistributor(newDistributor);

        assertTrue(c.rewardDistributor() == newDistributor, "rewardDistributor not updated after setRewardDistributor");
    }
}

